// js
const rate = get(ctx.entry, 'terms.rate', null);
if (rate == null) return false;
const engagement = String(get(ctx.entry, 'engagement', 'EMPLOYEE'));
return !['CONTRACTOR', 'CONSULTANT', 'PAYEE'].includes(engagement);

validate:
// js
const employer = get(ctx.subject.employer, 'entity_extension_data', {});
if (get(employer, 'minimum_wage_exempt', false) === true) return true;
const worksite = get(ctx.entry, 'terms.work_region', null);
const region =
	typeof worksite === 'string' && worksite !== ''
		? worksite
		: String(get(employer, 'region', ''));
const floor = get(employer, 'minimum_wage_400_business', false) === true
	? ctx.lookup.business_400
	: get(ctx.lookup.by_region, region, null);
if (floor === null) return true;
const rate = get(ctx.entry, 'terms.rate', {});
const unit = get(rate, 'unit', null);
const amount = Number(get(rate, 'amount', 0));
const hours = Number(get(ctx.entry, 'terms.normal_hours_per_day', 0));
// LPA s.68: a month is thirty normal days.
const days = 30;
const daily =
	unit === 'DAILY'
		? amount
		: unit === 'MONTHLY'
			? amount / days
			: amount * hours;
return daily >= floor;

